function parseHeader(line, lineNumber) {
  const trimmed = line.trimStart()
  let rest = trimmed

  // Check for [[...]] first
  let isArray = false
  if (rest.startsWith('[[')) {
    isArray = true
    rest = rest.slice(2)
  } else if (rest.startsWith('[')) {
    rest = rest.slice(1)
  } else {
    throw error(lineNumber, 'expected a table header')
  }

  // Parse the dotted name
  const { name, rest: afterName } = parseDottedName(rest, lineNumber)
  rest = afterName.trimStart()

  // Check for closing bracket
  if (isArray) {
    if (!rest.startsWith(']]')) {
      throw error(lineNumber, 'unterminated table header')
    }
    rest = rest.slice(2)
  } else {
    if (!rest.startsWith(']')) {
      throw error(lineNumber, 'unterminated table header')
    }
    rest = rest.slice(1)
  }

  rest = rest.trimStart()

  // Check for trailing content
  if (rest && rest[0] !== '#' && rest[0] !== ';') {
    throw error(lineNumber, 'trailing text after a table header')
  }

  return {
    type: isArray ? 'array' : 'table',
    path: name
  }
