    return { name: null, rest: str }
  }

  // Check for quoted string
  if (str[0] === '"' || str[0] === "'") {
    return parseString(str, lineNumber)
  }

  // Bare word: A-Z, a-z, 0-9, _, -
  let i = 0
  while (i < str.length && /[A-Za-z0-9_-]/.test(str[i])) {
    i++
  }

  if (i === 0) {
    return { name: null, rest: str }
  }

  return { name: str.slice(0, i), rest: str.slice(i) }
}

function parseKeyValue(line, lineNumber) {
  // Parse: <dotted name> = <value>

  // Find the = sign
  let commentIdx = findCommentIndex(line, lineNumber)
  const beforeComment = commentIdx === -1 ? line : line.slice(0, commentIdx)

  const eqIdx = beforeComment.indexOf('=')
  if (eqIdx === -1) {
    throw error(lineNumber, 'expected key = value')
  }

  const keyPart = beforeComment.slice(0, eqIdx)
  const valuePart = beforeComment.slice(eqIdx + 1)

  // Parse the dotted name
  const { name: keys, rest: afterKeys } = parseDottedName(keyPart, lineNumber)
  if (!keys || keys.length === 0) {
    throw error(lineNumber, 'expected a name')
  }

