function findCommentIndex(line, lineNumber) {
  let inString = false
  let stringChar = ''
  let i = 0

  while (i < line.length) {
    const ch = line[i]

    if (!inString) {
      if (ch === '"' || ch === "'") {
        inString = true
        stringChar = ch
      } else if (ch === '#' || ch === ';') {
        return i
      }
    } else {
      if (ch === stringChar && (stringChar === "'" || (stringChar === '"' && (i === 0 || line[i - 1] !== '\\')))) {
