    }
    i++
  }

  return -1
}

function parseValue(str, lineNumber) {
  if (!str) {
    throw error(lineNumber, 'expected a value')
  }

  const ch = str[0]

  // Check for comment at position 0 (shouldn't happen but be safe)
  if (ch === '#' || ch === ';') {
    throw error(lineNumber, 'expected a value')
  }

  // Boolean
  if (str.startsWith('true')) {
    const rest = str.slice(4)
    if (rest && !/[ \t#;,\]\}]/.test(rest[0])) {
      throw error(lineNumber, `invalid value ${getBareWord(str, lineNumber)}`)
    }
    return { value: true, rest }
  }

  if (str.startsWith('false')) {
    const rest = str.slice(5)
    if (rest && !/[ \t#;,\]\}]/.test(rest[0])) {
      throw error(lineNumber, `invalid value ${getBareWord(str, lineNumber)}`)
    }
    return { value: false, rest }
  }

  // String
  if (ch === '"') {
    return parseBasicString(str, lineNumber)
  }

  if (ch === "'") {
    return parseLiteralString(str, lineNumber)
  }

  // Array
  if (ch === '[') {
    return parseArray(str, lineNumber)
  }

  // Inline table
  if (ch === '{') {
    return parseInlineTable(str, lineNumber)
  }

  // Number or bare word
  return parseNumber(str, lineNumber)
}

function parseBasicString(str, lineNumber) {
  if (!str.startsWith('"')) {
    throw error(lineNumber, 'expected a string')
  }

  let result = ''
  let i = 1

  while (i < str.length) {
    const ch = str[i]

    if (ch === '"') {
      return { value: result, rest: str.slice(i + 1) }
    }

    if (ch === '\\') {
      if (i + 1 >= str.length) {
        throw error(lineNumber, 'unterminated string')
      }

      const nextCh = str[i + 1]
      switch (nextCh) {
        case '"':
          result += '"'
          i += 2
          break
        case '\\':
          result += '\\'
          i += 2
          break
        case 'n':
          result += '\n'
          i += 2
          break
        case 't':
          result += '\t'
          i += 2
          break
        case 'r':
          result += '\r'
          i += 2
          break
        case '0':
          result += '\0'
          i += 2
          break
        case 'u':
