    isFloat = true
    i++

    if (i < str.length && (str[i] === '+' || str[i] === '-')) {
      i++
    }

    if (i >= str.length || !/[0-9]/.test(str[i])) {
      const bareWord = getBareWord(str, lineNumber)
      throw error(lineNumber, `invalid value ${bareWord}`)
    }

    while (i < str.length && (/[0-9]/.test(str[i]) || str[i] === '_')) {
      if (str[i] === '_') {
        if (!(/[0-9]/.test(str[i - 1])) || !(/[0-9]/.test(str[i + 1]))) {
          const bareWord = getBareWord(str, lineNumber)
          throw error(lineNumber, `invalid value ${bareWord}`)
        }
      }
      i++
    }
  }

  // Check what comes after
  if (i < str.length && !/[ \t#;,\]\}]/.test(str[i])) {
    throw error(lineNumber, 'trailing text after a value')
  }

  const numStr = str.slice(0, i).replace(/_/g, '')
  const rest = str.slice(i)

  if (isFloat) {
    return { value: parseFloat(numStr), rest }
  } else {
    return { value: parseInt(numStr, 10), rest }
  }
}

function parseArray(str, lineNumber) {
  if (!str.startsWith('[')) {
    throw error(lineNumber, 'expected an array')
  }

  let i = 1
  const values = []
  let expectValue = true

  while (i < str.length) {
    const rest = str.slice(i).trimStart()

    if (!rest) {
      throw error(lineNumber, 'unterminated array')
    }

    if (rest[0] === ']') {
      return { value: values, rest: str.slice(str.indexOf(']', i) + 1) }
    }

    if (rest[0] === ',') {
      if (expectValue) {
        throw error(lineNumber, 'expected a value')
      }
      i += str.slice(i).indexOf(',') + 1
      expectValue = true
      continue
    }

    if (!expectValue) {
      throw error(lineNumber, 'expected a comma or closing bracket in array')
    }

    const { value, rest: afterValue } = parseValue(rest, lineNumber)
    values.push(value)
    i += str.slice(i).length - afterValue.length
    expectValue = false
  }

  throw error(lineNumber, 'unterminated array')
}

function parseInlineTable(str, lineNumber) {
  if (!str.startsWith('{')) {
    throw error(lineNumber, 'expected an inline table')
  }

  let i = 1
  const table = {}
  let expectKey = true

  while (i < str.length) {
    const rest = str.slice(i).trimStart()

    if (!rest) {
      throw error(lineNumber, 'unterminated inline table')
    }

    if (rest[0] === '}') {
      return { value: table, rest: str.slice(str.indexOf('}', i) + 1) }
    }

    if (rest[0] === ',') {
      if (expectKey) {
        throw error(lineNumber, 'expected a value')
      }
      i += str.slice(i).indexOf(',') + 1
      expectKey = true
      continue
    }

    if (!expectKey) {
      throw error(lineNumber, 'expected a comma or closing brace in inline table')
    }

    // Parse key = value
    const { name: keys, rest: afterKeys } = parseDottedName(rest, lineNumber)
    if (!keys || keys.length === 0) {
      throw error(lineNumber, 'expected a name')
    }

    let afterKeysStr = afterKeys.trimStart()
    if (!afterKeysStr.startsWith('=')) {
      throw error(lineNumber, 'expected = in an inline table')
    }

    afterKeysStr = afterKeysStr.slice(1).trimStart()
    const { value, rest: afterValue } = parseValue(afterKeysStr, lineNumber)

    // Place value in table following the dotted key
    let current = table
    for (let j = 0; j < keys.length - 1; j++) {
      const key = keys[j]
      if (!(key in current)) {
        current[key] = {}
      }
      current = current[key]
    }

    const lastKey = keys[keys.length - 1]
    if (lastKey in current) {
      throw error(lineNumber, `key ${keys.join('.')} is defined twice`)
    }
    current[lastKey] = value

    i += str.slice(i).length - afterValue.trimStart().length
    expectKey = false
  }

  throw error(lineNumber, 'unterminated inline table')
}

function getBareWord(str, lineNumber) {
  let i = 0
  while (i < str.length && !/[ \t#;,\]\}]/.test(str[i])) {
    i++
  }
  return str.slice(0, i)
}

function outputJSON(obj) {
  const json = JSON.stringify(obj, null, 2)
  process.stdout.write(json + '\n')
}

function outputKeys(obj, prefix = '') {
  const keys = Object.keys(obj).sort()

  for (const key of keys) {
    const value = obj[key]
    const path = prefix ? `${prefix}.${key}` : key

    if (Array.isArray(value)) {
      process.stdout.write(`${path} array\n`)

      for (const item of value) {
        if (typeof item === 'object' && item !== null && !Array.isArray(item)) {
          outputKeys(item, path)
        }
      }
    } else if (typeof value === 'object' && value !== null) {
      process.stdout.write(`${path} table\n`)
      outputKeys(value, path)
    } else if (typeof value === 'string') {
      process.stdout.write(`${path} string\n`)
    } else if (typeof value === 'boolean') {
      process.stdout.write(`${path} boolean\n`)
    } else if (Number.isInteger(value)) {
      process.stdout.write(`${path} integer\n`)
    } else if (typeof value === 'number') {
      process.stdout.write(`${path} float\n`)
    }
  }
}
