#!/usr/bin/env node

import { readFileSync } from 'fs'

// Parse command line arguments
const args = process.argv.slice(2)
if (args.length !== 1 || !['json', 'keys'].includes(args[0])) {
  process.stderr.write('error: usage: cli.js json|keys\n')
  process.exit(2)
}
const mode = args[0]

// Read stdin
let input = ''
try {
  input = readFileSync(0, 'utf8')
} catch (e) {
  // empty input is ok
}

// Parse the TOML document
try {
  const doc = parseTOML(input)

  if (mode === 'json') {
    outputJSON(doc)
  } else {
    outputKeys(doc)
  }
  process.exit(0)
} catch (err) {
  process.stderr.write(err.message + '\n')
  process.exit(2)
}

function error(lineNum, reason) {
  return new Error(`error: line ${lineNum}: ${reason}`)
}

function parseTOML(input) {
  const lines = input.split('\n')
  // Drop empty tail from trailing newline
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }

  const doc = {}
  let currentTable = doc
  let currentPath = []
  const definedTables = new Set()
  const definedKeys = new Map()

  for (let lineNum = 0; lineNum < lines.length; lineNum++) {
    const line = lines[lineNum]
    const lineNumber = lineNum + 1

    // Skip empty lines and comments
    const trimmed = line.replace(/^[ \t]+/, '')
    if (!trimmed || trimmed[0] === '#' || trimmed[0] === ';') {
      continue
    }

    // Check if it's a header
    if (line.trimStart()[0] === '[') {
      const parsed = parseHeader(line, lineNumber)

      if (parsed.type === 'array') {
        // [[name]]
        const path = parsed.path
        const pathStr = path.join('.')

        // Navigate to parent
        let parent = doc
        for (let i = 0; i < path.length - 1; i++) {
          const key = path[i]
          if (!(key in parent)) {
            parent[key] = {}
          } else if (typeof parent[key] !== 'object' || Array.isArray(parent[key])) {
            throw error(lineNumber, `${pathStr} is not a table`)
          }
          parent = parent[key]
        }

        const lastKey = path[path.length - 1]
        if (!(lastKey in parent)) {
          parent[lastKey] = []
        } else if (!Array.isArray(parent[lastKey])) {
          throw error(lineNumber, `${pathStr} is not an array of tables`)
        }

        const newTable = {}
        parent[lastKey].push(newTable)
        currentTable = newTable
        currentPath = path
      } else {
        // [name]
        const path = parsed.path
        const pathStr = path.join('.')

        // Mark as defined table
        if (definedTables.has(pathStr) && !isTableCreatedByDottedKey(definedTables, pathStr)) {
          throw error(lineNumber, `table ${pathStr} is defined twice`)
        }
        definedTables.add(pathStr)

        // Navigate/create the table
        let current = doc
        for (let i = 0; i < path.length; i++) {
          const key = path[i]
          const currentPathStr = path.slice(0, i + 1).join('.')

          if (!(key in current)) {
            current[key] = {}
            definedTables.add(currentPathStr)
          } else if (typeof current[key] !== 'object' || Array.isArray(current[key])) {
            throw error(lineNumber, `${currentPathStr} is not a table`)
          }
          current = current[key]
        }

        currentTable = current
        currentPath = path
      }
    } else {
      // Key-value assignment
      const parsed = parseKeyValue(line, lineNumber)
      const { keys, value } = parsed

      // Navigate to the correct table
      let current = currentTable
      const fullPath = [...currentPath, ...keys]

      for (let i = 0; i < keys.length - 1; i++) {
        const key = keys[i]
        const pathSoFar = [...currentPath, ...keys.slice(0, i + 1)].join('.')

        if (!(key in current)) {
          current[key] = {}
        } else if (typeof current[key] !== 'object' || Array.isArray(current[key])) {
          throw error(lineNumber, `${pathSoFar} is not a table`)
        }
        current = current[key]
      }

      const finalKey = keys[keys.length - 1]
      const fullKeyPath = fullPath.join('.')

      if (finalKey in current) {
        throw error(lineNumber, `key ${fullKeyPath} is defined twice`)
      }

      current[finalKey] = value
      definedKeys.set(fullKeyPath, lineNumber)
    }
  }

  return doc
}

function isTableCreatedByDottedKey(definedTables, path) {
  // A table created by dotted keys can be redefined by a header
  // This is a simplified check - for now just return true if it was created as intermediate
  return false
}

function parseHeader(line, lineNumber) {
  const trimmed = line.trimStart()
  let rest = trimmed

  // Check for [[...]] first
  let isArray = false
  if (rest.startsWith('[[')) {
    isArray = true
    rest = rest.slice(2)
  } else if (rest.startsWith('[')) {
    rest = rest.slice(1)
  } else {
    throw error(lineNumber, 'expected a table header')
  }

  // Parse the dotted name
  const { name, rest: afterName } = parseDottedName(rest, lineNumber)
  rest = afterName.trimStart()

  // Check for closing bracket
  if (isArray) {
    if (!rest.startsWith(']]')) {
      throw error(lineNumber, 'unterminated table header')
    }
    rest = rest.slice(2)
  } else {
    if (!rest.startsWith(']')) {
      throw error(lineNumber, 'unterminated table header')
    }
    rest = rest.slice(1)
  }

  rest = rest.trimStart()

  // Check for trailing content
  if (rest && rest[0] !== '#' && rest[0] !== ';') {
    throw error(lineNumber, 'trailing text after a table header')
  }

  return {
    type: isArray ? 'array' : 'table',
    path: name
  }
}

function parseDottedName(str, lineNumber) {
  const names = []
  let rest = str

  while (true) {
    rest = rest.trimStart()

    const { name, rest: afterName } = parseName(rest, lineNumber)
    if (!name) {
      throw error(lineNumber, 'expected a name')
    }

    names.push(name)
    rest = afterName.trimStart()

    if (rest.startsWith('.')) {
      rest = rest.slice(1)
    } else {
      break
    }
  }

  return { name: names, rest }
}

function parseName(str, lineNumber) {
  if (!str) {
    return { name: null, rest: str }
  }

  // Check for quoted string
  if (str[0] === '"' || str[0] === "'") {
    return parseString(str, lineNumber)
  }

  // Bare word: A-Z, a-z, 0-9, _, -
  let i = 0
  while (i < str.length && /[A-Za-z0-9_-]/.test(str[i])) {
    i++
  }

  if (i === 0) {
    return { name: null, rest: str }
  }

  return { name: str.slice(0, i), rest: str.slice(i) }
}

function parseKeyValue(line, lineNumber) {
  // Parse: <dotted name> = <value>

  // Find the = sign
  let commentIdx = findCommentIndex(line, lineNumber)
  const beforeComment = commentIdx === -1 ? line : line.slice(0, commentIdx)

  const eqIdx = beforeComment.indexOf('=')
  if (eqIdx === -1) {
    throw error(lineNumber, 'expected key = value')
  }

  const keyPart = beforeComment.slice(0, eqIdx)
  const valuePart = beforeComment.slice(eqIdx + 1)

  // Parse the dotted name
  const { name: keys, rest: afterKeys } = parseDottedName(keyPart, lineNumber)
  if (!keys || keys.length === 0) {
    throw error(lineNumber, 'expected a name')
  }

  // Check that nothing but whitespace between name and =
  if (afterKeys.trim()) {
    throw error(lineNumber, 'expected = in an inline table')
  }

  // Parse the value
  const { value, rest: afterValue } = parseValue(valuePart.trimStart(), lineNumber)

  // Check for trailing content
  const trailing = afterValue.trimStart()
  if (trailing && trailing[0] !== '#' && trailing[0] !== ';') {
    throw error(lineNumber, 'trailing text after a value')
  }

  return { keys, value }
}

function findCommentIndex(line, lineNumber) {
  let inString = false
  let stringChar = ''
  let i = 0

  while (i < line.length) {
    const ch = line[i]

    if (!inString) {
      if (ch === '"' || ch === "'") {
        inString = true
        stringChar = ch
      } else if (ch === '#' || ch === ';') {
        return i
      }
    } else {
      if (ch === stringChar && (stringChar === "'" || (stringChar === '"' && (i === 0 || line[i - 1] !== '\\')))) {
        // Check if it's properly escaped
        if (stringChar === '"') {
          let backslashCount = 0
          let j = i - 1
          while (j >= 0 && line[j] === '\\') {
            backslashCount++
            j--
          }
          if (backslashCount % 2 === 0) {
            inString = false
          }
        } else {
          inString = false
        }
      }
    }
    i++
  }

  return -1
}

function parseValue(str, lineNumber) {
  if (!str) {
    throw error(lineNumber, 'expected a value')
  }

  const ch = str[0]

  // Check for comment at position 0 (shouldn't happen but be safe)
  if (ch === '#' || ch === ';') {
    throw error(lineNumber, 'expected a value')
  }

  // Boolean
  if (str.startsWith('true')) {
    const rest = str.slice(4)
    if (rest && !/[ \t#;,\]\}]/.test(rest[0])) {
      throw error(lineNumber, `invalid value ${getBareWord(str, lineNumber)}`)
    }
    return { value: true, rest }
  }

  if (str.startsWith('false')) {
    const rest = str.slice(5)
    if (rest && !/[ \t#;,\]\}]/.test(rest[0])) {
      throw error(lineNumber, `invalid value ${getBareWord(str, lineNumber)}`)
    }
    return { value: false, rest }
  }

  // String
  if (ch === '"') {
    return parseBasicString(str, lineNumber)
  }

  if (ch === "'") {
    return parseLiteralString(str, lineNumber)
  }

  // Array
  if (ch === '[') {
    return parseArray(str, lineNumber)
  }

  // Inline table
  if (ch === '{') {
    return parseInlineTable(str, lineNumber)
  }

  // Number or bare word
  return parseNumber(str, lineNumber)
}

function parseBasicString(str, lineNumber) {
  if (!str.startsWith('"')) {
    throw error(lineNumber, 'expected a string')
  }

  let result = ''
  let i = 1

  while (i < str.length) {
    const ch = str[i]

    if (ch === '"') {
      return { value: result, rest: str.slice(i + 1) }
    }

    if (ch === '\\') {
      if (i + 1 >= str.length) {
        throw error(lineNumber, 'unterminated string')
      }

      const nextCh = str[i + 1]
      switch (nextCh) {
        case '"':
          result += '"'
          i += 2
          break
        case '\\':
          result += '\\'
          i += 2
          break
        case 'n':
          result += '\n'
          i += 2
          break
        case 't':
          result += '\t'
          i += 2
          break
        case 'r':
          result += '\r'
          i += 2
          break
        case '0':
          result += '\0'
          i += 2
          break
        case 'u':
          if (i + 5 >= str.length) {
            throw error(lineNumber, 'unterminated string')
          }
          const hex = str.slice(i + 2, i + 6)
          if (!/^[0-9a-fA-F]{4}$/.test(hex)) {
            throw error(lineNumber, `invalid escape \\${nextCh}`)
          }
          result += String.fromCharCode(parseInt(hex, 16))
          i += 6
          break
        default:
          throw error(lineNumber, `invalid escape \\${nextCh}`)
      }
    } else {
      result += ch
      i++
    }
  }

  throw error(lineNumber, 'unterminated string')
}

function parseLiteralString(str, lineNumber) {
  if (!str.startsWith("'")) {
    throw error(lineNumber, 'expected a string')
  }

  let i = 1
  while (i < str.length) {
    if (str[i] === "'") {
      return { value: str.slice(1, i), rest: str.slice(i + 1) }
    }
    i++
  }

  throw error(lineNumber, 'unterminated string')
}

function parseNumber(str, lineNumber) {
  // Integer or float
  let i = 0

  // Optional sign
  if (str[0] === '+' || str[0] === '-') {
    i++
  }

  // Digits with optional underscores
  if (i >= str.length || !/[0-9]/.test(str[i])) {
    const bareWord = getBareWord(str, lineNumber)
    throw error(lineNumber, `invalid value ${bareWord}`)
  }

  const start = i
  let hasUnderscore = false

  // Consume digits and underscores
  while (i < str.length && (/[0-9]/.test(str[i]) || str[i] === '_')) {
    if (str[i] === '_') {
      // Check that underscore is surrounded by digits
      if (i === start || !(/[0-9]/.test(str[i - 1])) || !(/[0-9]/.test(str[i + 1]))) {
        const bareWord = getBareWord(str, lineNumber)
        throw error(lineNumber, `invalid value ${bareWord}`)
      }
      hasUnderscore = true
    }
    i++
  }

  // Check if it's a float
  let isFloat = false

  if (i < str.length && str[i] === '.') {
    isFloat = true
    i++

    if (i >= str.length || !/[0-9]/.test(str[i])) {
      const bareWord = getBareWord(str, lineNumber)
      throw error(lineNumber, `invalid value ${bareWord}`)
    }

    while (i < str.length && (/[0-9]/.test(str[i]) || str[i] === '_')) {
      if (str[i] === '_') {
        if (i === start || !(/[0-9]/.test(str[i - 1])) || !(/[0-9]/.test(str[i + 1]))) {
          const bareWord = getBareWord(str, lineNumber)
          throw error(lineNumber, `invalid value ${bareWord}`)
        }
      }
      i++
    }
  }

  // Check for exponent
  if (i < str.length && (str[i] === 'e' || str[i] === 'E')) {
    isFloat = true
    i++

    if (i < str.length && (str[i] === '+' || str[i] === '-')) {
      i++
    }

    if (i >= str.length || !/[0-9]/.test(str[i])) {
      const bareWord = getBareWord(str, lineNumber)
      throw error(lineNumber, `invalid value ${bareWord}`)
    }

    while (i < str.length && (/[0-9]/.test(str[i]) || str[i] === '_')) {
      if (str[i] === '_') {
        if (!(/[0-9]/.test(str[i - 1])) || !(/[0-9]/.test(str[i + 1]))) {
          const bareWord = getBareWord(str, lineNumber)
          throw error(lineNumber, `invalid value ${bareWord}`)
        }
      }
      i++
    }
  }

  // Check what comes after
  if (i < str.length && !/[ \t#;,\]\}]/.test(str[i])) {
    throw error(lineNumber, 'trailing text after a value')
  }

  const numStr = str.slice(0, i).replace(/_/g, '')
  const rest = str.slice(i)

  if (isFloat) {
    return { value: parseFloat(numStr), rest }
  } else {
    return { value: parseInt(numStr, 10), rest }
  }
}

function parseArray(str, lineNumber) {
  if (!str.startsWith('[')) {
    throw error(lineNumber, 'expected an array')
  }

  let i = 1
  const values = []
  let expectValue = true

  while (i < str.length) {
    const rest = str.slice(i).trimStart()

    if (!rest) {
      throw error(lineNumber, 'unterminated array')
    }

    if (rest[0] === ']') {
      return { value: values, rest: str.slice(str.indexOf(']', i) + 1) }
    }

    if (rest[0] === ',') {
      if (expectValue) {
        throw error(lineNumber, 'expected a value')
      }
      i += str.slice(i).indexOf(',') + 1
      expectValue = true
      continue
    }

    if (!expectValue) {
      throw error(lineNumber, 'expected a comma or closing bracket in array')
    }

    const { value, rest: afterValue } = parseValue(rest, lineNumber)
    values.push(value)
    i += str.slice(i).length - afterValue.length
    expectValue = false
  }

  throw error(lineNumber, 'unterminated array')
}

function parseInlineTable(str, lineNumber) {
  if (!str.startsWith('{')) {
    throw error(lineNumber, 'expected an inline table')
  }

  let i = 1
  const table = {}
  let expectKey = true

  while (i < str.length) {
    const rest = str.slice(i).trimStart()

    if (!rest) {
      throw error(lineNumber, 'unterminated inline table')
    }

    if (rest[0] === '}') {
      return { value: table, rest: str.slice(str.indexOf('}', i) + 1) }
    }

    if (rest[0] === ',') {
      if (expectKey) {
        throw error(lineNumber, 'expected a value')
      }
      i += str.slice(i).indexOf(',') + 1
      expectKey = true
      continue
    }

    if (!expectKey) {
      throw error(lineNumber, 'expected a comma or closing brace in inline table')
    }

    // Parse key = value
    const { name: keys, rest: afterKeys } = parseDottedName(rest, lineNumber)
    if (!keys || keys.length === 0) {
      throw error(lineNumber, 'expected a name')
    }

    let afterKeysStr = afterKeys.trimStart()
    if (!afterKeysStr.startsWith('=')) {
      throw error(lineNumber, 'expected = in an inline table')
    }

    afterKeysStr = afterKeysStr.slice(1).trimStart()
    const { value, rest: afterValue } = parseValue(afterKeysStr, lineNumber)

    // Place value in table following the dotted key
    let current = table
    for (let j = 0; j < keys.length - 1; j++) {
      const key = keys[j]
      if (!(key in current)) {
        current[key] = {}
      }
      current = current[key]
    }

    const lastKey = keys[keys.length - 1]
    if (lastKey in current) {
      throw error(lineNumber, `key ${keys.join('.')} is defined twice`)
    }
    current[lastKey] = value

    i += str.slice(i).length - afterValue.trimStart().length
    expectKey = false
  }

  throw error(lineNumber, 'unterminated inline table')
}

function getBareWord(str, lineNumber) {
  let i = 0
  while (i < str.length && !/[ \t#;,\]\}]/.test(str[i])) {
    i++
  }
  return str.slice(0, i)
}

function outputJSON(obj) {
  const json = JSON.stringify(obj, null, 2)
  process.stdout.write(json + '\n')
}

function outputKeys(obj, prefix = '') {
  const keys = Object.keys(obj).sort()

  for (const key of keys) {
    const value = obj[key]
    const path = prefix ? `${prefix}.${key}` : key

    if (Array.isArray(value)) {
      process.stdout.write(`${path} array\n`)

      for (const item of value) {
        if (typeof item === 'object' && item !== null && !Array.isArray(item)) {
          outputKeys(item, path)
        }
      }
    } else if (typeof value === 'object' && value !== null) {
      process.stdout.write(`${path} table\n`)
      outputKeys(value, path)
    } else if (typeof value === 'string') {
      process.stdout.write(`${path} string\n`)
    } else if (typeof value === 'boolean') {
      process.stdout.write(`${path} boolean\n`)
    } else if (Number.isInteger(value)) {
      process.stdout.write(`${path} integer\n`)
    } else if (typeof value === 'number') {
      process.stdout.write(`${path} float\n`)
    }
  }
}

